    @staticmethod
    @function_wrapper
    def log_rfrl_version():
        test_logger(f"You are using {str(pkg_resources.get_distribution('taf-rfrl-csv4all')).replace('-', '.')}")

    def get_execution_log_link(self):
        if self.cm_execution:
            try:
                with open("/opt/ute/execution.context.json", 'r') as file:
                    data = json.load(file)
                    return data.get("CM_LOG_LINK", None)
            except Exception as e:
                test_logger(f"Execution log link not found {e}", "info", False)
                test_logger(traceback.format_exc(), log_level="debug", console=False)
                return ""
        return None

    def get_final_results(self):
        passed_iterations = sum(nodes_result == "passed" for nodes_result in self.test_results.values())
        failed_iterations = sum(nodes_result == "failed" for nodes_result in self.test_results.values())
        failed_iterations_numbers = [iteration.split("_")[1] for iteration, nodes_result in
                                     self.test_results.items()
                                     if nodes_result == "failed"]
        remaining_iterations = self.iterations_per_node - (passed_iterations + failed_iterations)
        number_of_failed_iterations = f"\tIterations numbers: {', '.join(failed_iterations_numbers)}" \
            if failed_iterations_numbers else ""
        final_results = f"Passed iterations: {passed_iterations}\n" \
                        f"Failed iterations: {failed_iterations} {number_of_failed_iterations}\n" \
                        f"Remaining iterations: {remaining_iterations}"
        return final_results

    @method_decorator()
    def send_email(self, state: str, msg: str = ""):
        try:
            iteration_number = self.current_iteration.split("_")[1] if self.current_iteration else "1"
            email_body = EmailFormat(self.nodes, self.test_nodes, self.report_to_rp, self.test_reporter,
                                     self.iterations_per_node, state, msg, self.topology,
                                     self.get_execution_log_link(), self.test_results,
                                     iteration_number)
            self.notifications.send_email(body=str(email_body),
                                          subject=f"CSV4ALL {self.test_name_titlecase} {state.upper()} on "
                                                  f"{', '.join([node.hostname for node in self.test_nodes])}")
        except Exception as e:
            test_logger(e, "warn")

    @staticmethod
    @function_wrapper
    def check_free_space():
        free_space_home = float(psutil.disk_usage("/home/ute").free) / (1024 ** 3)
        free_space_tmp = float(psutil.disk_usage("/tmp").free) / (1024 ** 3)
        test_logger(f"There is {round(free_space_home, 2)} GB of free space in /home/ute ")
        test_logger(f"There is {round(free_space_tmp, 2)} GB of free space in /tmp")
        if free_space_home < 5 or free_space_tmp < 1:
            raise FatalError(f"Not enough free space for test to start. Available space in: \n"
                             f"/home/ute {round(free_space_home, 2)} GB\n/tmp {round(free_space_tmp, 2)} GB")
        return True

    def get_all_allowed_faults(self):
        return self.allowed_faults_on_shared_rmods + self.allowed_faults_for_slave + \
            self.allowed_faults_on_radio_master + self.allowed_faults_for_sync_slave + \
            self.allowed_faults_on_radio_slave

