    def verify_failed_nodes_after_iteration(self):
        if any([self.failed_nodes[node] for node in self.failed_nodes]):
            failed_nodes = {node: failed_node for node, failed_node in self.failed_nodes.copy().items() if failed_node}
            raise IterationFailedError(f"Iteration {self.current_iteration.split('_')[1]} Failed. "
                                       f"Issues detected on nodes : {failed_nodes}")
        else:
            test_logger(f"Iteration No. {self.current_iteration.split('_')[1]} Passed", hyperlink=True)

    def _collect_passed_logs(self):
        log_dir = f"{self.log_dir}/{self.current_iteration}_passed_logs"
        if os.path.exists(log_dir):
            self._remove_directory(log_dir)
        shutil.copytree(f"{self.log_dir}/{self.current_iteration}", log_dir)
        self.passed_logs_gathered = True

    def is_critical_alarm_detected(self) -> bool:
        for node in self.nodes:
            if node.btsverify.critical_alarm_detected:
                return True

    def _critical_alarms_teardown(self):
        test_logger(f"Final Results : {dict(self.test_results)}", console=False)
        raise FatalError("Critical Alarm Detected!")

    def _summary_test_iteration(self, result: str, wrapper: RobotWrapper):
        self.teardown_nodes()
        self.test_results[self.current_iteration] = result
        if result == "failed" and self.notifications:
            self.send_email("failed", self.email_message)
        test_logger(self.get_final_results())
        self.stop_test_log_tracing(logs_dir=f"{self.log_dir}/{self.current_iteration}")
        wrapper.close_level_to(max(wrapper.levels.keys()) - 1)
        if self.test_results[self.current_iteration] == "passed":
            if not self.passed_logs_gathered:
                self._collect_passed_logs()
            if not self.precheck_failed:
                self._remove_directory(f"{self.log_dir}/{self.current_iteration}")
        if self.is_critical_alarm_detected():
            self._critical_alarms_teardown()
        if self.stop_test_after_fail and result == "failed":
            raise FatalError("Test has been stopped, stop_test_after_fail is True")

    def _set_current_logs_dir(self, node):
        self.current_logs_dir = os.path.join(self.log_dir, self.current_iteration, f"TEST_ON_{node.node_alias}")

    def _restore_instance_attributes(self):
        self.failed_nodes.clear()
        self.precheck_failed = False
        for node in self.test_nodes:
            node.logsverify.logs_fault_message = ""
            node.btsverify.bts_fault_message = ""

    def _send_email_on_mumin_failure(self):
        test_hostname_nodes = self.test_nodes[0].hostname
        if self.mumin.failed_rmods and self.notifications:
            self.notifications.send_email(
                body=str(f"Serial library setup setup failed:\n\n {self.mumin.failed_rmods}"),
                subject=f"CSV4ALL MUMIN SETUP FAILURE FOR {test_hostname_nodes}", text_type="plain")
        if self.mumin.faulty_rmods and self.notifications:
            self.notifications.send_email(
                body=str(f"Serial library connected successfully but had following troubles: "
                         f"\n\n{self.mumin.faulty_rmods}"),
                subject=f"CSV4ALL MUMIN SETUP WARNING FOR {test_hostname_nodes}", text_type="plain")

    def __prepare_test_name(self):
        tc_name = self.__class__.__name__
        uuf_sufix = ""
        if "UUF" in tc_name:
            tc_name = re.sub(r"UUF", "", tc_name)
            uuf_sufix = "UUF "
        return uuf_sufix + " ".join(re.findall(r'[A-Z][a-z]*', tc_name))

    def __remove_disconnect_ims_files(self):
        try:
            for node in self.test_nodes:
                ddisconnect_dir = f"{self.log_dir}/{node.node_alias}"
                _path = Path(ddisconnect_dir)
                if _path.exists():
                    for filename in os.listdir(ddisconnect_dir):
                        path = os.path.join(ddisconnect_dir, filename)
                        if "_disconnect_at_" in filename:
                            os.remove(path)
        except Exception as e:
            test_logger(e, "DEBUG")

