    @staticmethod
    def _remove_directory(directory: str):
        try:
            def iter_dir(path):
                directory_path = Path(path)
                for file in directory_path.iterdir():
                    if file.is_file():
                        file.unlink()
                    else:
                        iter_dir(file)

            iter_dir(directory)
            shutil.rmtree(directory)
        except OSError as error:
            test_logger(f"Couldn't remove directory: {directory}", "ERROR")
            test_logger(error, "DEBUG")

