    @function_wrapper
    def set_target_sw(self):
        for node in self.test_nodes:
            if not node.target_sw:
                node.target_sw = node.get_active_sw()

    def remove_hwf_flag(self, node):
        if node.remove_hwf_flag_if_exists():
            node.reset_site()
            node.verify_node_bts_state()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.multi_runner.verify_all_nodes()

    def _set_passed_log_gathering(self):
        if self.collect_passed_logs > 0:
            if (self.current_iteration_number % self.collect_passed_logs) == 0:
                self.passed_logs_gathered = False
            else:
                self.passed_logs_gathered = True

    def teardown_nodes(self):
        for node in self.nodes:
            node.node_teardown()

    @method_decorator()
    def restore_base_scf(self, node):
        self._set_current_logs_dir(node)
        try:
            self.start_test_log_tracing()
            self.add_all_allowed_specific_faults(node)
            self.multi_runner.start_watching_alarms_on_all_nodes()
            status = verify_function_x_times(3, 30, node.restore_base_scf)
            failed_nodes = set()
            if "failed" not in status:
                failed_nodes = self.multi_runner.verify_all_nodes()
            if "failed" in status or failed_nodes:
                test_logger(f"Nodes failed during restoring base scf: {','.join(failed_nodes)}", "error")
                self.gather_mumin_logs_and_snapshot("restoring_scf")
                raise IterationFailedError(f"Iteration {self.current_iteration.split('_')[1]} Failed. "
                                           f"Issues detected on nodes : {failed_nodes}")
        finally:
            self.multi_runner.stop_log_tracing_and_download_from_all_nodes(f"{self.current_logs_dir}/restoring_scf")

    @method_decorator()
    def setup_energy_saving(self):
        for node in self.test_nodes:
            if node.setup_energy_saving:
                try:
                    node.perform_setup_energy_saving()
                except SetupEnergySavingFailed as energy_saving_state:
                    test_logger(energy_saving_state, "ERROR")
                    raise energy_saving_state

    @method_decorator()
    def restoring_energy_saving(self):
        if any(node.energy_saving_instance and node.energy_saving_instance.energy_saving_groups
               for node in self.test_nodes):
            self.setup_admin_connections()
        for node in self.test_nodes:
            node.btsverify.cells_verifier.energy_saving_cells.clear()
            if node.energy_saving_instance and node.energy_saving_instance.energy_saving_groups:
                node.disable_energy_saving()
                self.restore_base_scf(node)

    @method_decorator()
    def add_flags_via_ru_manager(self):
        for node in self.test_nodes:
            if node.ru_manager:
                node.add_flags_on_rmods()

    @method_decorator()
    def restore_flags_via_ru_manager(self):
        for node in self.test_nodes:
            if node.ru_manager:
                try:
                    node.admin.setup_node_admin()
                    node.restore_flags_on_rmods()
                except Exception as e:
                    test_logger(e, "DEBUG")
                    test_logger("Restoring flags has failed", "ERROR")
                finally:
                    node.node_teardown()

